import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ARAnalysis {
  title: string;
  description: string;
  category: string;
  estimatedValue?: string;
  funFact: string;
}

export enum AppState {
  IDLE = 'IDLE',
  SCANNING = 'SCANNING',
  ANALYZING = 'ANALYZING',
  RESULT = 'RESULT',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { ARAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  // Remove data URL prefix if present
  const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: cleanBase64,
            },
          },
          {
            text: "Analyze this image for an Augmented Reality overlay. Identify the main object or scene. Provide a short title, a concise description (max 2 sentences), a general category, an estimated value (or 'N/A' if nature/public), and one short fun fact.",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: {
              type: Type.STRING,
              description: "Name of the object or scene",
            },
            description: {
              type: Type.STRING,
              description: "Brief visual description",
            },
            category: {
              type: Type.STRING,
              description: "Category of the item (e.g., Electronics, Nature, Food)",
            },
            estimatedValue: {
              type: Type.STRING,
              description: "Rough price estimate or 'Priceless/N/A'",
            },
            funFact: {
              type: Type.STRING,
              description: "A short, interesting fact about the subject",
            },
          },
          required: ["title", "description", "category", "funFact"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini");
    }

    return JSON.parse(text) as ARAnalysis;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    throw new Error("Failed to analyze the image. Please try again.");
  }
};

import React, { useEffect, useRef, useState } from 'react';

interface CameraFeedProps {
  onCapture: (imageData: string) => void;
  isPaused: boolean;
}

export const CameraFeed: React.FC<CameraFeedProps> = ({ onCapture, isPaused }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'environment', // Use back camera on mobile
            width: { ideal: 1920 },
            height: { ideal: 1080 }
          },
          audio: false
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Camera access denied or unavailable.");
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run once on mount

  useEffect(() => {
    if (videoRef.current) {
      if (isPaused) {
        videoRef.current.pause();
      } else {
        videoRef.current.play().catch(e => console.log("Play interrupted", e));
      }
    }
  }, [isPaused]);

  // Expose capture method via ref or imperative handle is complex, so we pass a trigger function or expose via prop?
  // Simpler: The parent triggers capture logic, but here we just listen for a signal?
  // Even better: We pass a function "capture" up to parent? No, parent asks to capture.
  // Let's use `useImperativeHandle` or just put the logic in the capture button in parent using a ref to this component.
  // Refactoring: Let's actually pass a ref from parent or use an event listener.
  // Simplest React pattern: Logic inside this component, triggered by a prop change or just exposing the capture functionality.

  // Re-thinking: The Parent needs the image. The Parent controls the UI.
  // Let's expose a method to the parent via Ref.

  // Actually, we can just export a helper function or keep it simple.
  // Let's modify: This component renders the video. The Parent renders a button that calls a function. 
  // We need to give the parent access to the video element to capture the frame.

  // Let's forward the ref to the video element.
  return (
    <div className="fixed inset-0 w-full h-full bg-black z-0">
      {error && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-900 text-white p-4 text-center">
          <p>{error}</p>
        </div>
      )}
      {/* Hidden canvas for capturing frames */}
      <canvas ref={canvasRef} className="hidden" />

      <video
        ref={videoRef}
        autoPlay
        playsInline
        muted
        className={`w-full h-full object-cover transition-opacity duration-300 ${isPaused ? 'opacity-50 blur-sm' : 'opacity-100'}`}
      />

      {/* Capture trigger wrapper - effectively this component exposes the capture capability */}
      <div className="hidden">
         <button id="capture-trigger" onClick={() => {
            if (videoRef.current && canvasRef.current) {
                const video = videoRef.current;
                const canvas = canvasRef.current;
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
                    onCapture(dataUrl);
                }
            }
         }} />
      </div>
    </div>
  );
};

