import React, { useState, useCallback } from 'react';
import { CameraFeed } from './components/CameraFeed';
import { Overlay } from './components/Overlay';
import { ScannerEffect } from './components/ScannerEffect';
import { analyzeImage } from './services/geminiService';
import { ARAnalysis, AppState } from './types';
import { Search, Loader2, Camera } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [analysisResult, setAnalysisResult] = useState<ARAnalysis | null>(null);

  // Trigger the hidden button inside CameraFeed to get the image
  const triggerCapture = () => {
    const btn = document.getElementById('capture-trigger');
    if (btn) btn.click();
  };

  const handleImageCapture = useCallback(async (imageData: string) => {
    setAppState(AppState.ANALYZING);
    try {
      const data = await analyzeImage(imageData);
      setAnalysisResult(data);
      setAppState(AppState.RESULT);
    } catch (error) {
      console.error(error);
      setAppState(AppState.ERROR);
      // Auto reset after error
      setTimeout(() => setAppState(AppState.IDLE), 3000);
    }
  }, []);

  const resetScanner = () => {
    setAppState(AppState.IDLE);
    setAnalysisResult(null);
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* 1. Camera Layer */}
      <CameraFeed 
        onCapture={handleImageCapture} 
        isPaused={appState === AppState.RESULT || appState === AppState.ANALYZING} 
      />

      {/* 2. State: Scanning Animation */}
      {appState === AppState.ANALYZING && <ScannerEffect />}

      {/* 3. State: Idle (Controls) */}
      {appState === AppState.IDLE && (
        <div className="absolute bottom-0 left-0 w-full p-8 pb-12 flex justify-center items-center z-20 bg-gradient-to-t from-black/80 to-transparent">
            <button
              onClick={triggerCapture}
              className="relative group"
            >
              <div className="absolute inset-0 bg-cyan-500 rounded-full blur opacity-40 group-hover:opacity-60 transition-opacity duration-300"></div>
              <div className="relative w-20 h-20 rounded-full border-4 border-white flex items-center justify-center bg-white/10 backdrop-blur-sm shadow-xl transition-transform transform group-hover:scale-105 active:scale-95">
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center">
                    <Search className="text-black w-8 h-8" />
                </div>
              </div>
              <span className="absolute -top-10 left-1/2 -translate-x-1/2 text-white font-mono text-xs bg-black/40 px-2 py-1 rounded">
                TAP TO SCAN
              </span>
            </button>
        </div>
      )}

      {/* 4. State: Result Overlay */}
      {appState === AppState.RESULT && analysisResult && (
        <Overlay data={analysisResult} onReset={resetScanner} />
      )}

      {/* 5. State: Error */}
      {appState === AppState.ERROR && (
        <div className="absolute inset-0 z-30 flex items-center justify-center bg-black/80 backdrop-blur-sm">
           <div className="text-center p-6 bg-red-900/50 border border-red-500 rounded-xl">
             <Loader2 className="w-10 h-10 text-red-500 animate-spin mx-auto mb-2" />
             <h3 className="text-white font-bold">Analysis Failed</h3>
             <p className="text-red-200 text-sm">Retrying connection...</p>
           </div>
        </div>
      )}

      {/* Header / Logo */}
      <div className="absolute top-0 left-0 w-full p-6 z-20 flex justify-between items-center bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-cyan-500 rounded flex items-center justify-center">
                <Camera className="text-white w-5 h-5" />
            </div>
            <div>
                <h1 className="text-white font-bold text-lg leading-none tracking-wider">AR LENS</h1>
                <p className="text-cyan-400 text-[10px] font-mono leading-none">POWERED BY GEMINI</p>
            </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
        .animate-scan {
          animation: scan 2s linear infinite;
        }
        @keyframes slide-up {
            from { transform: translateY(100%); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
        }
        .animate-slide-up {
            animation: slide-up 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
      `}</style>
    </div>
  );
};

export default App;

export interface ARAnalysis {
  detected: boolean;
  title?: string;
  description?: string;
  category?: string;
  estimatedValue?: string;
  funFact?: string;
}

export enum AppState {
  IDLE = 'IDLE',         // Searching/Scanning automatically
  ANALYZING = 'ANALYZING', // Sending data (background)
  DETECTED = 'DETECTED',   // Object found, transition animation
  RESULT = 'RESULT',     // Showing info
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { ARAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: cleanBase64,
            },
          },
          {
            text: `You are an Augmented Reality Object Detector. 
            Analyze the image. Is there a clear, distinct object in focus (like a statue, monument, electronic device, vehicle, or person)? 

            1. If the image is blurry, too dark, or contains only generic background/floor/ceiling, set "detected" to false.
            2. If a specific object is found (especially a statue of a man/warrior, or any monument), set "detected" to true and provide details.

            Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            detected: {
              type: Type.BOOLEAN,
              description: "True if a clear, analyzable object is found. False if blurry or empty.",
            },
            title: {
              type: Type.STRING,
              description: "Name of the object",
            },
            description: {
              type: Type.STRING,
              description: "2 sentence visual description",
            },
            category: {
              type: Type.STRING,
              description: "Category (e.g. Statue, Landmark)",
            },
            estimatedValue: {
              type: Type.STRING,
              description: "Price or 'Priceless'",
            },
            funFact: {
              type: Type.STRING,
              description: "One short fun fact",
            },
          },
          required: ["detected"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    return JSON.parse(text) as ARAnalysis;
  } catch (error) {
    console.error("Analysis Error:", error);
    // Return a safe "not detected" object on error so app keeps scanning
    return { detected: false };
  }
};

import React from 'react';

interface ScannerEffectProps {
  isLocked?: boolean;
}

export const ScannerEffect: React.FC<ScannerEffectProps> = ({ isLocked = false }) => {
  return (
    <div className="absolute inset-0 z-10 pointer-events-none flex items-center justify-center">
      {/* Target Reticle Container */}
      <div className={`relative transition-all duration-500 ease-out ${isLocked ? 'w-64 h-64 scale-100' : 'w-48 h-48 scale-110 opacity-80'}`}>

        {/* Corners */}
        <div className={`absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 transition-colors duration-300 ${isLocked ? 'border-green-400' : 'border-white/50'}`}></div>
        <div className={`absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 transition-colors duration-300 ${isLocked ? 'border-green-400' : 'border-white/50'}`}></div>
        <div className={`absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 transition-colors duration-300 ${isLocked ? 'border-green-400' : 'border-white/50'}`}></div>
        <div className={`absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 transition-colors duration-300 ${isLocked ? 'border-green-400' : 'border-white/50'}`}></div>

        {/* Center Crosshair / Scan Line */}
        {!isLocked && (
          <>
            <div className="absolute top-1/2 left-1/2 w-4 h-4 bg-white/50 rounded-full -translate-x-1/2 -translate-y-1/2"></div>
            <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-transparent via-cyan-400/20 to-transparent animate-scan-fast"></div>
          </>
        )}

        {/* Locked State Effect */}
        {isLocked && (
           <div className="absolute inset-0 border-2 border-green-500/50 bg-green-500/10 animate-pulse">
             <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-green-400 font-mono font-bold tracking-widest text-sm bg-black/60 px-2 py-0.5 rounded">
               TARGET ACQUIRED
             </div>
           </div>
        )}
      </div>

      {/* Scanning Text */}
      {!isLocked && (
        <div className="absolute bottom-20 text-white/70 font-mono text-xs tracking-[0.2em] animate-pulse">
          SEARCHING TARGET...
        </div>
      )}

      <style>{`
        @keyframes scan-fast {
          0% { transform: translateY(-100%); opacity: 0; }
          50% { opacity: 1; }
          100% { transform: translateY(100%); opacity: 0; }
        }
        .animate-scan-fast {
          animation: scan-fast 1.5s cubic-bezier(0.4, 0, 0.2, 1) infinite;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { CameraFeed } from './components/CameraFeed';
import { Overlay } from './components/Overlay';
import { ScannerEffect } from './components/ScannerEffect';
import { analyzeImage } from './services/geminiService';
import { ARAnalysis, AppState } from './types';
import { Camera, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [analysisResult, setAnalysisResult] = useState<ARAnalysis | null>(null);
  const isProcessingRef = useRef(false);

  // Trigger capture programmatically
  const triggerCapture = () => {
    const btn = document.getElementById('capture-trigger');
    if (btn) btn.click();
  };

  // The capture handler (called by CameraFeed)
  const handleImageCapture = useCallback(async (imageData: string) => {
    // If already processing or showing result, ignore new frames
    if (isProcessingRef.current || appState === AppState.RESULT) return;

    isProcessingRef.current = true;

    // We don't change state to ANALYZING immediately to avoid UI flickering during silent scans
    // We only show visual feedback if detection takes a while or is confirmed.

    try {
      const data = await analyzeImage(imageData);

      if (data.detected) {
        // FOUND IT!
        setAnalysisResult(data);
        setAppState(AppState.DETECTED);

        // Short delay to show "Lock On" effect before showing card
        setTimeout(() => {
          setAppState(AppState.RESULT);
        }, 1000);
      } else {
        // Not detected, stay in IDLE to keep scanning
        console.log("Scanning... nothing clear found.");
      }
    } catch (error) {
      console.error(error);
      // Ignore errors in auto-scan mode, just keep retrying
    } finally {
      isProcessingRef.current = false;
    }
  }, [appState]);

  // Auto-Scan Loop
  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    if (appState === AppState.IDLE) {
      intervalId = setInterval(() => {
        if (!isProcessingRef.current) {
          triggerCapture();
        }
      }, 2000); // Check every 2 seconds
    }

    return () => clearInterval(intervalId);
  }, [appState]);

  const resetScanner = () => {
    setAnalysisResult(null);
    setAppState(AppState.IDLE);
    isProcessingRef.current = false;
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* 1. Camera Layer */}
      <CameraFeed 
        onCapture={handleImageCapture} 
        isPaused={appState === AppState.RESULT} 
      />

      {/* 2. State: Scanning / Detecting Visuals */}
      {(appState === AppState.IDLE || appState === AppState.ANALYZING || appState === AppState.DETECTED) && (
        <ScannerEffect isLocked={appState === AppState.DETECTED} />
      )}

      {/* 3. State: Result Overlay */}
      {appState === AppState.RESULT && analysisResult && (
        <Overlay data={analysisResult} onReset={resetScanner} />
      )}

      {/* Header */}
      <div className="absolute top-0 left-0 w-full p-6 z-20 flex justify-between items-center bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-green-500 rounded flex items-center justify-center animate-pulse">
                <Zap className="text-black w-5 h-5 fill-current" />
            </div>
            <div>
                <h1 className="text-white font-bold text-lg leading-none tracking-wider">AUTO LENS</h1>
                <p className="text-green-400 text-[10px] font-mono leading-none">AI TRACKING ACTIVE</p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default App;

