      // Ignore errors in auto-scan mode, just keep retrying
    } finally {
      isProcessingRef.current = false;
    }
  }, [appState]);

  // Auto-Scan Loop
  useEffect(() => {
    let intervalId: ReturnType<typeof setInterval>;

    if (appState === AppState.IDLE) {
      intervalId = setInterval(() => {
        if (!isProcessingRef.current) {
          triggerCapture();
        }
      }, 2000); // Check every 2 seconds
    }

    return () => clearInterval(intervalId);
  }, [appState]);

  const resetScanner = () => {
    setAnalysisResult(null);
    setAppState(AppState.IDLE);
    isProcessingRef.current = false;
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* 1. Camera Layer */}
      <CameraFeed 
        onCapture={handleImageCapture} 
        isPaused={appState === AppState.RESULT} 
      />

      {/* 2. State: Scanning / Detecting Visuals */}
      {(appState === AppState.IDLE || appState === AppState.ANALYZING || appState === AppState.DETECTED) && (
        <ScannerEffect isLocked={appState === AppState.DETECTED} />
      )}

      {/* 3. State: Result Overlay */}
      {appState === AppState.RESULT && analysisResult && (
        <Overlay data={analysisResult} onReset={resetScanner} />
      )}

      {/* Header */}
      <div className="absolute top-0 left-0 w-full p-6 z-20 flex justify-between items-center bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-green-500 rounded flex items-center justify-center animate-pulse">
                <Zap className="text-black w-5 h-5 fill-current" />
            </div>
            <div>
                <h1 className="text-white font-bold text-lg leading-none tracking-wider">AUTO LENS</h1>
                <p className="text-green-400 text-[10px] font-mono leading-none">AI TRACKING ACTIVE</p>
            </div>
        </div>
      </div>
    </div>
  );
};

