import { GoogleGenAI, Type } from "@google/genai";
import { ARAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: cleanBase64,
            },
          },
          {
            text: `Target Identification Task:
            Look specifically for a statue of a shirtless male warrior/figure holding a vertical pole or spear. 
            The figure is usually standing on a platform, has defined muscles, and is wearing a loincloth/skirt. The pose is dynamic with one arm outstretched or holding the pole.

            1. If this SPECIFIC statue is clearly visible in the image, return detected: true.
            2. If the image is blurry, generic, or contains other things (cars, people, random buildings), return detected: false.

            Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            detected: {
              type: Type.BOOLEAN,
              description: "True ONLY if the specific warrior statue is found.",
            },
          },
          required: ["detected"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    return JSON.parse(text) as ARAnalysis;
  } catch (error) {
    console.error("Analysis Error:", error);
    return { detected: false };
  }
};

