import React, { useState, useCallback, useEffect, useRef } from 'react';
import { CameraFeed } from './components/CameraFeed';
import { ARObject } from './components/ARObject';
import { ScannerEffect } from './components/ScannerEffect';
import { analyzeImage } from './services/geminiService';
import { ARAnalysis, AppState } from './types';
import { Zap, Box } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const isProcessingRef = useRef(false);

  // Trigger capture programmatically
  const triggerCapture = () => {
    const btn = document.getElementById('capture-trigger');
    if (btn) btn.click();
  };

  const handleImageCapture = useCallback(async (imageData: string) => {
    // If we have already found the object (RESULT state), stop processing new frames
    if (isProcessingRef.current || appState === AppState.RESULT) return;

    isProcessingRef.current = true;

    try {
      const data = await analyzeImage(imageData);

      if (data.detected) {
        // Target Found: Switch to RESULT state immediately to show AR Object
        setAppState(AppState.RESULT);
      } else {
        console.log("Scanning... target not found.");
      }
    } catch (error) {
      console.error(error);
    } finally {
      // Only release the lock if we didn't find it. 
      // If we found it, we stay in RESULT state until user resets.
      if (appState !== AppState.RESULT) {
          isProcessingRef.current = false;
      }
    }
  }, [appState]);

  // Continuous Scanning Loop
  useEffect(() => {
    let intervalId: ReturnType<typeof setInterval>;

    if (appState === AppState.IDLE) {
      intervalId = setInterval(() => {
        // Only trigger if not currently processing a request
        if (!isProcessingRef.current) {
          triggerCapture();
        }
      }, 1500); // Fast scan interval (1.5s)
    }

    return () => clearInterval(intervalId);
  }, [appState]);

  const resetAR = () => {
    setAppState(AppState.IDLE);
    isProcessingRef.current = false;
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* 1. Camera Feed (Always Active) */}
      {/* We don't pause the video in AR mode so it looks like the object is floating in the real world */}
      <CameraFeed 
        onCapture={handleImageCapture} 
        isPaused={false} 
      />

      {/* 2. State: Idle / Scanning Visuals */}
      {appState === AppState.IDLE && (
        <ScannerEffect isLocked={false} />
      )}

      {/* 3. State: AR Object (The "Kotak") */}
      {appState === AppState.RESULT && (
        <>
            {/* Remove scanner effect, show 3D Object */}
            <ARObject onClose={resetAR} />
        </>
      )}

      {/* Header */}
      <div className="absolute top-0 left-0 w-full p-6 z-20 flex justify-between items-center bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex items-center space-x-2">
            <div className={`w-8 h-8 rounded flex items-center justify-center transition-colors duration-300 ${appState === AppState.RESULT ? 'bg-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.8)]' : 'bg-gray-800'}`}>
                <Box className={`w-5 h-5 ${appState === AppState.RESULT ? 'text-white' : 'text-gray-400'}`} />
            </div>
            <div>
                <h1 className="text-white font-bold text-lg leading-none tracking-wider">WARRIOR AR</h1>
                <p className={`${appState === AppState.RESULT ? 'text-cyan-400' : 'text-gray-400'} text-[10px] font-mono leading-none transition-colors`}>
                    {appState === AppState.RESULT ? 'OBJECT AUGMENTED' : 'SEARCHING TARGET...'}
                </p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default App;

