import { GoogleGenAI, Type } from "@google/genai";
import { ARAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: cleanBase64,
            },
          },
          {
            text: `Object Detection Task:
            Look for "Monumen Yudha Mandala Utama" in Buleleng, Bali.

            Visual Characteristics:
            - A statue of a Balinese warrior/hero (often depicting muscle, traditional attire/kamben).
            - Holding a weapon (bamboo runcing or keris) pointing forward or upward.
            - Standing on a tall pedestal/pillar.
            - Located in a park/open space area.

            Return JSON: { "detected": true } if this specific monument or a very similar warrior statue is clearly visible. Otherwise false.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            detected: {
              type: Type.BOOLEAN,
            },
          },
          required: ["detected"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    return JSON.parse(text) as ARAnalysis;
  } catch (error) {
    console.error("Analysis Error:", error);
    return { detected: false };
  }
};

