const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>(ViewMode.SPLASH);
  const [isTargetFound, setIsTargetFound] = useState(false);

  // Quiz State
  const [quizToken, setQuizToken] = useState("");
  const [isQuizUnlocked, setIsQuizUnlocked] = useState(false);
  const [quizError, setQuizError] = useState("");

  const isProcessingRef = useRef(false);

  // -- SPLASH SCREEN LOGIC --
  useEffect(() => {
    if (view === ViewMode.SPLASH) {
      const timer = setTimeout(() => {
        setView(ViewMode.HOME);
      }, 3500); // 3.5s loading time
      return () => clearTimeout(timer);
    }
  }, [view]);

  // -- CAPTURE LOGIC --
  const triggerCapture = () => {
    const btn = document.getElementById('capture-trigger');
    if (btn) btn.click();
  };

  const handleImageCapture = useCallback(async (imageData: string) => {
    // Only process in SCAN mode. If in Info/Quiz, we pause processing to save resources.
    if (isProcessingRef.current || (view !== ViewMode.SCAN && view !== ViewMode.INFO && view !== ViewMode.QUIZ)) return;

    // Only process in SCAN mode
    if (view !== ViewMode.SCAN) return;

    isProcessingRef.current = true;

    try {
      const data = await analyzeImage(imageData);

      // LOGIC: If detected -> Show Object. If not detected -> Hide Object.
      if (data.detected) {
        setIsTargetFound(true);
      } else {
        setIsTargetFound(false);
      }
    } catch (error) {
      console.error("Scanning error:", error);
      // If detection fails (error), we consider it "Lost" to be safe
      setIsTargetFound(false);
    } finally {
      // Release lock so we can scan again immediately
      isProcessingRef.current = false;
    }
  }, [view]);

  // Auto-scan loop - CONTINUOUS
  useEffect(() => {
    let intervalId: ReturnType<typeof setInterval>;

    // Run interval when in SCAN mode, REGARDLESS of whether target is found or not.
    // This allows us to "Lose" the target if the camera moves away.
    if (view === ViewMode.SCAN) {
      intervalId = setInterval(() => {
        if (!isProcessingRef.current) triggerCapture();
      }, 2000); // Check every 2 seconds
    }
    return () => clearInterval(intervalId);
  }, [view]);

  // -- HELPERS --
  const checkToken = () => {
    if (quizToken.trim().toUpperCase() === "MERDEKA" || quizToken === "1234") {
