/**
 * LOCAL COMPUTER VISION SERVICE
 * Menggantikan AI dengan algoritma pengenalan bentuk sederhana (Edge Detection).
 * Mendeteksi kompleksitas visual (tepi & kontras) untuk mensimulasikan pengenalan objek.
 */

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  return new Promise((resolve) => {
    const img = new Image();

    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        resolve({ detected: false });
        return;
      }

      // 1. Resize gambar agar proses ringan (64x64 pixel cukup untuk deteksi pola)
      const size = 64;
      canvas.width = size;
      canvas.height = size;

      // Draw gambar ke canvas
      ctx.drawImage(img, 0, 0, size, size);

      // 2. Ambil data pixel
      const imageData = ctx.getImageData(0, 0, size, size);
      const data = imageData.data;

      let edgeScore = 0;

      // 3. Algoritma Deteksi Tepi Sederhana (Simple Edge Detection)
      // Kita membandingkan perbedaan kontras pixel saat ini dengan pixel sebelahnya.
      // Objek seperti Patung/Monumen memiliki banyak "tepi" (kontras tinggi) dibanding tembok rata.

      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size - 1; x++) {
          const i = (y * size + x) * 4;

          // Konversi ke Grayscale (R+G+B)/3
          const brightness1 = (data[i] + data[i+1] + data[i+2]) / 3;
          const brightness2 = (data[i+4] + data[i+5] + data[i+6]) / 3;

          // Hitung selisih kontras (absolut)
          const diff = Math.abs(brightness1 - brightness2);

          // Jika bedanya tajam, tambahkan ke skor
          edgeScore += diff;
        }
      }

      // Normalisasi skor berdasarkan jumlah pixel
      const averageEdgeScore = edgeScore / (size * size);

      // DEBUG: Lihat skor di console untuk tuning sensitivitas
      // Tembok polos biasanya < 5. Wajah/Objek Kompleks biasanya > 15.
      // console.log("Visual Complexity Score:", averageEdgeScore);

      // 4. Threshold Logic
      // Jika skor kompleksitas visual > 12, kita asumsikan itu adalah objek (Monumen)
      // Angka 12 adalah "Magic Number" hasil eksperimen untuk membedakan objek vs background polos.
      const DETECTION_THRESHOLD = 12; 

      const isDetected = averageEdgeScore > DETECTION_THRESHOLD;

      // Simulasi delay sedikit agar terasa seperti "scanning" (opsional, 200ms)
      setTimeout(() => {
          resolve({ detected: isDetected });
      }, 200);
    };

    img.onerror = () => {
        resolve({ detected: false });
    };

    img.src = base64Image;
  });
};

