/**
 * LOCAL COMPUTER VISION SERVICE
 * Menggantikan AI dengan algoritma pengenalan bentuk sederhana (Edge Detection).
 * Mendeteksi kompleksitas visual (tepi & kontras) untuk mensimulasikan pengenalan objek.
 */

export const analyzeImage = async (base64Image: string): Promise<ARAnalysis> => {
  return new Promise((resolve) => {
    const img = new Image();

    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        resolve({ detected: false, matchPercentage: 0 });
        return;
      }

      // 1. Resize gambar agar proses ringan (64x64 pixel cukup untuk deteksi pola)
      const size = 64;
      canvas.width = size;
      canvas.height = size;

      // Draw gambar ke canvas
      ctx.drawImage(img, 0, 0, size, size);

      // 2. Ambil data pixel
      const imageData = ctx.getImageData(0, 0, size, size);
      const data = imageData.data;

      let edgeScore = 0;

      // 3. Algoritma Deteksi Tepi Sederhana (Simple Edge Detection)
      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size - 1; x++) {
          const i = (y * size + x) * 4;

          // Konversi ke Grayscale (R+G+B)/3
          const brightness1 = (data[i] + data[i+1] + data[i+2]) / 3;
          const brightness2 = (data[i+4] + data[i+5] + data[i+6]) / 3;

          // Hitung selisih kontras (absolut)
          const diff = Math.abs(brightness1 - brightness2);

          // Jika bedanya tajam, tambahkan ke skor
          edgeScore += diff;
        }
      }

      // Normalisasi skor berdasarkan jumlah pixel
      const averageEdgeScore = edgeScore / (size * size);

      // 4. Threshold Logic & Progress Calculation
      // Menurunkan Threshold dari 12 menjadi 8 agar lebih mudah terdeteksi.
      const DETECTION_THRESHOLD = 8; 

      // Hitung persentase (Cap di 100%)
      // Jika score 4 (setengah threshold), progress = 50%
      let percentage = (averageEdgeScore / DETECTION_THRESHOLD) * 100;
      if (percentage > 100) percentage = 100;

      // Agar bar tidak terlalu "jumpy" di nilai rendah, kita bisa beri sedikit bias
      // atau biarkan raw.

      const isDetected = averageEdgeScore > DETECTION_THRESHOLD;

      setTimeout(() => {
          resolve({ 
              detected: isDetected,
              matchPercentage: Math.floor(percentage)
          });
      }, 100); // Sedikit lebih cepat dari sebelumnya
    };

    img.onerror = () => {
        resolve({ detected: false, matchPercentage: 0 });
    };

    img.src = base64Image;
  });
};

