import React, { useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Text } from '@react-three/drei';
import * as THREE from 'three';
import { MONUMENT_INFO } from '../types';

// Fix for missing JSX types in React Three Fiber
declare global {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      mesh: any;
      boxGeometry: any;
      meshStandardMaterial: any;
      cylinderGeometry: any;
      coneGeometry: any;
      torusGeometry: any;
      ambientLight: any;
      spotLight: any;
      pointLight: any;
    }
  }
}

// Procedural 3D Model representing the Monument
// Since we don't have a GLTF URL, we construct a representation using Primitives
// Symbolizing the "Bambu Runcing" (Bamboo Spear) and the struggle mentioned in history.
const MonumentModel = (props: any) => {
  const groupRef = useRef<THREE.Group>(null);

  // Animate the monument slightly
  useFrame((state) => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.005;
      // Gentle floating effect is handled by <Float> wrapper
    }
  });

  return (
    <group ref={groupRef} {...props} dispose={null}>
      {/* --- BASE STRUCTURE (Stone Pedestal) --- */}
      {/* Bottom Step */}
      <mesh position={[0, -2, 0]} receiveShadow>
        <boxGeometry args={[3, 0.4, 3]} />
        <meshStandardMaterial color="#4a4a4a" roughness={0.8} />
      </mesh>

      {/* Middle Step */}
      <mesh position={[0, -1.6, 0]} receiveShadow>
        <boxGeometry args={[2.2, 0.4, 2.2]} />
        <meshStandardMaterial color="#5a5a5a" roughness={0.8} />
      </mesh>

      {/* Top Pedestal */}
      <mesh position={[0, -1.0, 0]} receiveShadow>
        <cylinderGeometry args={[0.8, 1, 1.2, 8]} />
        <meshStandardMaterial color="#6b6b6b" roughness={0.6} />
      </mesh>

      {/* --- MAIN PILLAR (Symbolizing Courage/Heroism) --- */}
      <mesh position={[0, 0.5, 0]} castShadow>
        <boxGeometry args={[0.6, 3, 0.6]} />
        <meshStandardMaterial color="#8B4513" roughness={0.3} />
      </mesh>

      {/* --- BAMBOO RUNCING SYMBOL (Golden Spear) --- */}
      <group position={[0, 2, 0]}>
         {/* Shaft */}
         <mesh position={[0, 1, 0]}>
            <cylinderGeometry args={[0.1, 0.15, 3, 16]} />
            <meshStandardMaterial color="#FFD700" metalness={0.8} roughness={0.2} />
         </mesh>
         {/* Tip */}
         <mesh position={[0, 2.7, 0]}>
            <coneGeometry args={[0.1, 0.5, 16]} />
            <meshStandardMaterial color="#FFD700" metalness={1} roughness={0.1} emissive="#ffaa00" emissiveIntensity={0.2} />
         </mesh>
      </group>

      {/* --- DECORATIVE ELEMENTS --- */}
      {/* Floating Rings */}
      <mesh position={[0, 0, 0]} rotation={[0.5, 0, 0]}>
        <torusGeometry args={[1.5, 0.05, 16, 100]} />
        <meshStandardMaterial color="orange" emissive="orange" emissiveIntensity={2} toneMapped={false} />
      </mesh>

       <mesh position={[0, 0.5, 0]} rotation={[-0.5, 0, 0]}>
        <torusGeometry args={[1.2, 0.03, 16, 100]} />
        <meshStandardMaterial color="cyan" emissive="cyan" emissiveIntensity={2} toneMapped={false} />
      </mesh>

      {/* 3D Text Label */}
      <Text
        position={[0, -2.5, 1.6]}
        fontSize={0.3}
        color="white"
        anchorX="center"
        anchorY="middle"
      >
        YUDHA MANDALA
      </Text>
    </group>
  );
};

export const ARObject: React.FC = () => {
  return (
    <div className="absolute inset-0 z-30 w-full h-full fade-in">
      <Canvas shadows dpr={[1, 2]}>
        <PerspectiveCamera makeDefault position={[0, 2, 6]} fov={50} />

        {/* Lighting */}
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={1} castShadow />
        <pointLight position={[-10, -10, -10]} intensity={0.5} />

        {/* Environment Reflection */}
        <Environment preset="sunset" />

