                <div className="animate-fade-in">
                     <div className="text-left mb-6">
                        <span className="text-orange-500 text-xs font-bold">PERTANYAAN 1/3</span>
                        <p className="text-white font-medium mt-2 text-lg">Apa makna bambu runcing pada patung Yudha Mandala?</p>
                     </div>

                     <div className="space-y-3 mb-6">
                        <button onClick={() => alert("Kurang Tepat!")} className="w-full p-4 rounded-xl bg-gray-800 text-gray-300 hover:bg-gray-700 border border-transparent hover:border-gray-500 transition-all text-sm text-left">
                            A. Keindahan Seni
                        </button>
                        <button onClick={() => alert("Benar! Melambangkan keberanian.")} className="w-full p-4 rounded-xl bg-gray-800 text-gray-300 hover:bg-green-900/30 border border-transparent hover:border-green-500 transition-all text-sm text-left flex justify-between items-center group">
                            B. Semangat Perjuangan Rakyat
                            <CheckCircle className="w-4 h-4 opacity-0 group-hover:opacity-100 text-green-500" />
                        </button>
                        <button onClick={() => alert("Kurang Tepat!")} className="w-full p-4 rounded-xl bg-gray-800 text-gray-300 hover:bg-gray-700 border border-transparent hover:border-gray-500 transition-all text-sm text-left">
                            C. Hiasan Taman
                        </button>
                     </div>

                     <button onClick={closeOverlay} className="text-gray-500 text-sm hover:text-white underline">
                        Keluar dari Kuis
                     </button>
                </div>
            )}
        </div>
     </div>
  );

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans select-none">

      {/* 
        3. CAMERA CONTROL 
        shouldActive prop ensures camera is only running when view is SCAN/INFO/QUIZ.
        If user goes back to HOME, CameraFeed component will shut down the stream.
      */}
      <div className={`absolute inset-0 transition-opacity duration-1000 ${!isCameraActive ? 'opacity-0' : 'opacity-100'}`}>
         <CameraFeed onCapture={handleImageCapture} shouldActive={isCameraActive} />
      </div>

      {/* 2. AR Layers */}
      {isCameraActive && (
        <>
            {/* Top Bar */}
            <div className="absolute top-0 left-0 w-full p-4 z-40 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent pointer-events-none">
                <button onClick={() => { setIsTargetFound(false); setView(ViewMode.HOME); }} className="pointer-events-auto w-10 h-10 rounded-full bg-black/40 backdrop-blur border border-white/20 flex items-center justify-center text-white hover:bg-white/10 transition-colors">
                    <ChevronLeft className="w-6 h-6" />
                </button>
                <div className="bg-orange-500/20 border border-orange-500/50 px-4 py-1.5 rounded-full backdrop-blur animate-fade-in">
                    <span className="text-orange-400 text-xs font-mono font-bold tracking-widest">{isTargetFound ? 'TARGET LOCKED' : 'SEARCHING...'}</span>
                </div>
                <div className="w-10"></div>
            </div>

            {/* 3D Scene */}
            {isTargetFound ? <ARObject /> : <ScannerEffect isLocked={false} progress={scanProgress} />}

            {/* Bottom Interaction Bar */}
            {isTargetFound && view === ViewMode.SCAN && (
                <div className="absolute bottom-8 left-0 w-full px-6 z-40 flex gap-4 justify-center animate-fade-in">
                    <button onClick={() => setView(ViewMode.INFO)} className="flex-1 glass-panel py-4 rounded-2xl flex items-center justify-center gap-2 text-white hover:bg-white/20 active:scale-95 transition-all shadow-lg border-b-4 border-cyan-900/50">
                        <Info className="w-5 h-5 text-cyan-400" />
                        <span className="font-bold text-sm tracking-wide">INFORMASI</span>
                    </button>
                    <button onClick={() => setView(ViewMode.QUIZ)} className="flex-1 glass-panel py-4 rounded-2xl flex items-center justify-center gap-2 text-white hover:bg-white/20 active:scale-95 transition-all shadow-lg border-b-4 border-yellow-900/50">
                        <Trophy className="w-5 h-5 text-yellow-400" />
                        <span className="font-bold text-sm tracking-wide">KUIS</span>
                    </button>
                </div>
            )}
        </>
      )}

      {/* 3. Interface Layers */}
      {view === ViewMode.SPLASH && renderSplash()}
      {view === ViewMode.HOME && renderHome()}
      {view === ViewMode.INFO && renderInfoOverlay()}
      {view === ViewMode.QUIZ && renderQuizOverlay()}

      {view === ViewMode.ABOUT && (
          <div className="absolute inset-0 z-50 bg-black/90 flex flex-col items-center justify-center p-6 text-center animate-fade-in">
              <h2 className="text-2xl font-bold text-white mb-4">Tentang Aplikasi</h2>
              <p className="text-gray-400 mb-6 leading-relaxed">YudamandalaAR adalah media pembelajaran interaktif yang dibuat untuk melestarikan nilai sejarah Buleleng melalui teknologi modern.</p>
              <div className="mb-8">
                  <p className="text-xs text-gray-500 uppercase tracking-widest mb-2">Developed By</p>
                  <p className="text-orange-500 font-bold">TRIGANTALAPATI STUDIO</p>
              </div>
              <button onClick={() => setView(ViewMode.HOME)} className="bg-white/10 hover:bg-white/20 border border-white/20 px-8 py-3 rounded-full text-white font-bold text-sm transition-all">Kembali</button>
          </div>
      )}

    </div>
  );
};

export default App;

import React, { Suspense, Component, ReactNode } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Text, useGLTF, Center, Html, useProgress } from '@react-three/drei';
import { MONUMENT_INFO } from '../types';

// Fix for missing JSX types in React Three Fiber
declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
      primitive: any;
      ambientLight: any;
      spotLight: any;
      pointLight: any;
      group: any;
      mesh: any;
      boxGeometry: any;
      meshStandardMaterial: any;
    }
  }
}

declare global {
  namespace JSX {
    interface IntrinsicElements {
      primitive: any;
      ambientLight: any;
      spotLight: any;
      pointLight: any;
      group: any;
      mesh: any;
      boxGeometry: any;
      meshStandardMaterial: any;
    }
  }
}

// --- ERROR BOUNDARY ---
interface ErrorBoundaryProps {
  children: ReactNode;
  fallback: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(_: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Failed to load 3D model:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback;
    }
    return this.props.children;
  }
}

// --- LOADER COMPONENT ---
function Loader() {
  const { progress } = useProgress();
  return (
    <Html center>
      <div className="flex flex-col items-center justify-center bg-black/80 backdrop-blur-md p-4 rounded-xl border border-orange-500/50 shadow-[0_0_30px_rgba(234,88,12,0.4)]">
        <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin mb-2"></div>
        <p className="text-orange-400 font-mono text-xs font-bold tracking-widest">MEMUAT MODEL...</p>
        <p className="text-white font-mono text-sm">{progress.toFixed(0)}%</p>
      </div>
    </Html>
  );
}

// --- FALLBACK MODEL (ERROR STATE) ---
// Shown ONLY if yuda.glb is missing or corrupt
const FallbackModel = () => {
  return (
    <group>
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[2, 2, 2]} />
        <meshStandardMaterial color="red" wireframe />
      </mesh>
      <Text position={[0, 1.5, 0]} fontSize={0.3} color="white" background="red" anchorX="center" anchorY="bottom">
        ERROR: FILE 3D TIDAK DITEMUKAN!
      </Text>
      <Text position={[0, 1.1, 0]} fontSize={0.15} color="white" anchorX="center" anchorY="bottom">
        Pastikan file 'yuda.glb' ada di folder 'public'
      </Text>
    </group>
  )
}

// --- 3D MODEL COMPONENT ---
const YudaModel = (props: any) => {
  // LOAD FILE: yuda.glb
  // Pastikan file ini ada di folder /public/yuda.glb
  const { scene } = useGLTF('/yuda.glb');

  // Clone scene to avoid mutation issues if reused
  const sceneClone = React.useMemo(() => scene.clone(), [scene]);

  return <primitive object={sceneClone} {...props} />;
};

export const ARObject: React.FC = () => {
  return (
    <div className="absolute inset-0 z-30 w-full h-full fade-in">
      <Canvas shadows dpr={[1, 2]}>
        <PerspectiveCamera makeDefault position={[0, 1, 6]} fov={45} />

        {/* Environment & Lighting - Optimized for GLB visibility */}
        <ambientLight intensity={1.5} />
        <spotLight 
          position={[10, 10, 10]} 
          angle={0.5} 
          penumbra={1} 
          intensity={2} 
          castShadow 
          shadow-mapSize={[1024, 1024]}
        />
        <pointLight position={[-10, -10, -10]} intensity={1} color="white" />

        <Environment preset="city" />

        {/* Async Loading Wrapper with Error Boundary */}
        <Suspense fallback={<Loader />}>
            <ErrorBoundary fallback={
                <Float speed={5} rotationIntensity={0.5} floatIntensity={0.5}>
                    <FallbackModel />
                </Float>
            }>
                <Float 
                    speed={2} 
                    rotationIntensity={0.2} 
                    floatIntensity={0.5}
                    floatingRange={[-0.1, 0.1]}
                >
                    <Center top>
                        {/* 
                            TAMPILKAN MODEL 'yuda.glb' 
                            Scale disesuaikan agar tidak terlalu kecil/besar
                        */}
                        <YudaModel scale={2} rotation={[0, Math.PI / 4, 0]} />
                    </Center>
                </Float>
            </ErrorBoundary>
        </Suspense>

        {/* Floor Shadow */}
        <ContactShadows position={[0, -2, 0]} opacity={0.5} scale={10} blur={2.5} far={4} />

        {/* Controls */}
        <OrbitControls 
            enablePan={false} 
            minPolarAngle={0} 
            maxPolarAngle={Math.PI / 1.5}
            minDistance={2}
            maxDistance={10}
            autoRotate
            autoRotateSpeed={2}
        />
      </Canvas>

      {/* Floating HTML Label */}
      <div className="absolute bottom-32 left-1/2 -translate-x-1/2 pointer-events-none w-full flex justify-center">
        <div className="bg-black/60 backdrop-blur-md border-l-4 border-orange-500 px-6 py-3 rounded-r-xl shadow-2xl transform transition-all hover:scale-105">
            <h2 className="text-orange-400 text-[10px] font-bold tracking-widest uppercase mb-1">AR VISUALIZER</h2>
            <h1 className="text-white text-lg font-bold leading-none">{MONUMENT_INFO.title}</h1>
            <p className="text-gray-400 text-[10px] mt-1">Model 3D: yuda.glb</p>
        </div>
      </div>
    </div>
  );
};

