  // Quiz State
  const [quizToken, setQuizToken] = useState("");
  const [isQuizUnlocked, setIsQuizUnlocked] = useState(false);
  const [quizError, setQuizError] = useState("");

  const isProcessingRef = useRef(false);

  // -- MOBILE DETECTION & LOCK SYSTEM --
  useEffect(() => {
    const checkMobile = () => {
      const userAgent = navigator.userAgent || navigator.vendor || (window as any).opera;
      // Detect if device is strictly mobile or tablet, OR if window width is small enough
      const isMobileDevice = /android|iPad|iPhone|iPod/i.test(userAgent) || window.innerWidth <= 1024;
      setIsMobile(isMobileDevice);
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // -- SPLASH SCREEN LOGIC --
  useEffect(() => {
    if (view === ViewMode.SPLASH) {
      const timer = setTimeout(() => {
        setView(ViewMode.HOME);
