// Fix for missing JSX types in React Three Fiber
declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
      primitive: any;
      ambientLight: any;
      spotLight: any;
      pointLight: any;
      group: any;
      mesh: any;
