import { QuizQuestion, StudentData } from "../types";

const API_URL = "https://script.google.com/macros/s/AKfycbw0Nb3b4_u7ZWhwiWMSLNWz0Gux5GnvEQ76xoVYyyl6ra2nYF3aFdSOvU7Qi6Vx_TOwFw/exec";
const QUIZ_ID = "YUDA_AR";

export const validateTokenAPI = async (token: string): Promise<StudentData> => {
    try {
        // action=login&token=...
        const response = await fetch(`${API_URL}?action=login&token=${encodeURIComponent(token)}`);

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status}`);
        }

        const data = await response.json();

        // Handle API specific error responses
        if (data.status === 'error' || data.result === 'error') {
             throw new Error(data.message || "Token tidak valid");
        }

        // Fallback checks if API response structure varies
        const name = data.name || data.nama || data.studentName;
        if (!name) throw new Error("Data siswa tidak ditemukan");

        return {
            name: name,
            token: token,
            className: data.className || data.class || data.kelas || "-"
        };
    } catch (error: any) {
        console.error("Login Error:", error);
        throw new Error(error.message || "Gagal menghubungkan ke server");
    }
};

export const getQuestionsAPI = async (): Promise<QuizQuestion[]> => {
    try {
        // action=getQuestions&quizId=YUDA_AR
        const response = await fetch(`${API_URL}?action=getQuestions&quizId=${QUIZ_ID}`);
        if (!response.ok) throw new Error("Gagal mengambil soal");

        const data = await response.json();

        // Handle response wrapper if any (e.g. { questions: [...] } or just [...])
        // Also handle C# compatible JSON which might be { items: [...] }
        const rawQuestions = Array.isArray(data) ? data : (data.questions || data.items || []);

        if (rawQuestions.length === 0) throw new Error("Tidak ada soal tersedia");

        // Map to internal structure
        return rawQuestions.map((q: any, index: number) => ({
            id: q.id || index + 1,
            question: q.question || q.text || "Pertanyaan error",
            options: (Array.isArray(q.options) ? q.options : []).map((opt: any, idx: number) => {
                // Handle different option formats
                const isObject = typeof opt === 'object' && opt !== null;
                return {
                    id: ["A", "B", "C", "D"][idx] || String(idx),
                    text: isObject ? (opt.text || opt.label || opt.answer) : String(opt),
                    isCorrect: isObject ? (opt.isCorrect === true || opt.isCorrect === "true") : false
                };
            })
        }));
    } catch (error: any) {
        console.error("Get Questions Error:", error);
        throw new Error(error.message || "Gagal memuat soal");
    }
};

export const submitScoreAPI = async (token: string, score: number): Promise<any> => {
    try {
        // action=submitScore&token=...&score=...&quizId=YUDA_AR
        const url = `${API_URL}?action=submitScore&token=${encodeURIComponent(token)}&score=${score}&quizId=${QUIZ_ID}`;

        // Using GET as simple GAS deployments often use doGet for everything. 
        // If POST is required by the specific script, this needs to change to method: 'POST'.
        // Based on "GetQuestions" and "Login" patterns typically being GET, we assume GET here too.
        const response = await fetch(url);
        return await response.json();
    } catch (error) {
        console.error("Submit Score Error:", error);
        return { status: "error", message: "Failed to submit" };
    }
};

import React, { useState, useEffect } from 'react';
