public class GameManager : MonoBehaviour {
    // GANTI URL INI DENGAN DEPLOYMENT ANDA
    private string apiUrl = "https://script.google.com/macros/s/AKfycbw0Nb3b4_u7ZWhwiWMSLNWz0Gux5GnvEQ76xoVYyyl6ra2nYF3aFdSOvU7Qi6Vx_TOwFw/exec"; 

    public void Login(string userToken) {
        StartCoroutine(PostLogin(userToken));
    }

    IEnumerator PostLogin(string token) {
        LoginRequest req = new LoginRequest { token = token };
        string json = JsonUtility.ToJson(req);

        using (UnityWebRequest www = UnityWebRequest.Post(apiUrl, json, "application/json")) {
            yield return www.SendWebRequest();

            if (www.result == UnityWebRequest.Result.Success) {
                Debug.Log("Login Sukses: " + www.downloadHandler.text);
                // Parsing JSON disini untuk ambil Nama, GameID, dan Soal
            } else {
                Debug.LogError("Error: " + www.error);
            }
        }
    }

    public void SendScore(string token, int score, string gameId) {
        StartCoroutine(PostScore(token, score, gameId));
